        if row[field] != value: _refuse_unless_reformat(row, field, value)
        r = db.amend_extraction(xid, field, value, "proto", session="session_proto", dry_run=False)
        print(xid, field, repr(value), "ACCEPTED", r.get("changed"))
    except Refusal as e:
        print(xid, field, repr(value), "REFUSED", str(e)[:110])
